# CUDA kernel and launcher
# ----------------------------------------------------------------------
cpp_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

void batched_matmul_fp16_launcher(const torch::Tensor& A,
                                  const torch::Tensor& B,
                                  torch::Tensor& C);
'''

cuda_source = r'''
extern "C" __global__
void batched_matmul_fp16(const __half* A,
                         const __half* B,
                         __half* C,
                         int batch,
                         int M,
                         int K,
                         int N) {
    const int TILE_M = 16;
    const int TILE_N = 16;
    const int TILE_K = 16;

    __shared__ __half As[TILE_M][TILE_K];
    __shared__ __half Bs[TILE_K][TILE_N];

    int batch_idx = blockIdx.z;
    const __half* A_batch = A + batch_idx * M * K;
    const __half* B_batch = B + batch_idx * K * N;
    __half* C_batch = C + batch_idx * M * N;

    int row = blockIdx.y * TILE_M + threadIdx.y;
    int col = blockIdx.x * TILE_N + threadIdx.x;

    float acc = 0.0f;

    for (int t = 0; t < K; t += TILE_K) {
        // Load A tile
        int a_row = row;
        int a_col = t + threadIdx.x;
        if (a_row < M && a_col < K)
            As[threadIdx.y][threadIdx.x] = A_batch[a_row * K + a_col];
        else
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);

        // Load B tile
        int b_row = t + threadIdx.y;
        int b_col = col;
        if (b_row < K && b_col < N)
            Bs[threadIdx.y][threadIdx.x] = B_batch[b_row * N + b_col];
        else
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc += __half2float(As[threadIdx.y][kk]) *
                   __half2float(Bs[kk][threadIdx.x]);
        }
        __syncthreads();
    }

    if (row < M && col < N) {
        C_batch[row * N + col] = __float2half(acc);
    }
}

void batched_matmul_fp16_launcher(const torch::Tensor& A,
                                  const torch::Tensor& B,
                                  torch::Tensor& C) {
    const int batch = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int N = B.size(2);

    const dim3 block(16, 16);
    const dim3 grid((N + 15) / 16,
                    (M + 15) / 16,
                    batch);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(A.scalar_type(),
        "batched_matmul_fp16_launcher", ([&] {
            batched_matmul_fp16<<<grid, block>>>(
                reinterpret_cast<const __half*>(A.data_ptr()),
                reinterpret_cast<const __half*>(B.data_ptr()),
                reinterpret_cast<__half*>(C.data_ptr()),
                batch, M, K, N);
        })
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
}
'''

# Compile the extension
_ext = load_inline(name='batched_matmul_fp16',
                   cpp_sources=cpp_source,
                   cuda_sources=cuda_source,
                   functions=['batched_matmul_fp16_launcher'],
                   verbose=False)

