# Model definition using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for torch.bmm using a custom fp16 CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure correct dtype and device
        if A.dtype != torch.float16:
            A = A.to(torch.float16)
        if B.dtype != torch.float16:
            B = B.to(torch.float16)
        A = A.contiguous()
        B = B.contiguous()

        batch, m, k = A.shape
        _, k2, n = B.shape
        assert k == k2, "Inner dimensions must match"

        C = torch.empty((batch, m, n), dtype=torch.float16, device=A.device)
        _ext.batched_matmul_fp16_launcher(A, B, C)
        return C
